properties.$st-css:
:import{
    -st-from: 'wix-ui-santa/index.st.css';
    -st-named: StylableButton
}
.root{
    -st-extends: StylableButton;
    transition: all 0.2s ease, visibility 0s;
    padding: 3px;
    box-shadow:;
    /*inset 3.54px 3.54px 0 -64px value(site_1_1)*/ border: 4px double value(site_1_1); background: #B4BBAC
}
.root:hover{
    background: value(site_1_1);
    border: 3px double rgb(11, 47, 91)
}
.root:hover::label{
    color: value(site_1_5)
}
.root:disabled{
    background: #E2E2E2
}
.root:disabled::label{
    color: #8F8F8F
}
.root:disabled::icon{
    fill: #8F8F8F
}
.root::container{
    transition: inherit
}
.root::label{
    transition: inherit;
    color: value(site_1_1);
    font-weight: normal;
    font-style: normal;
    font-family: "playfair display",serif;
    display: initial;
    letter-spacing: 0.15em;
    font-size: 14px
}
.root::icon{
    transition: inherit;
    width: 10px;
    height: 10px;
    fill: value(site_1_1);
    display: none
}
.root:hover::icon{
    fill: value(site_1_5)
}
@media value(mobileMediaQuery) {
    .root::label {
        font-size: 8px;
    }
}

.root::tabsList::scrollButton:hover {
    padding: 6px;
    padding-top: 0px;
    padding-bottom: 0px;
    background-color: #B2BEB0;
}
.root::tabsList::scrollButton:isVisible {
    padding: 6px;
    padding-top: 0px;
    padding-bottom: 0px;
    background-color: #B2BEB0;
    padding-left: 4px;
}:import{-st-from: 'wix-ui-santa/index.st.css';-st-named: Tabs}.root{-st-extends: Tabs}.root::tabsList::tab {
    color: #000000;
    font-size: 16px;
    font-family: avenir-lt-w01_35-light1475496,avenir-lt-w05_35-light,sans-serif;
    background-color: #DBDBDB;
}.root::tabsList::tab:current {
    background-color: value(color_36);
    color: value(color_37);
}.root::tabsList::scrollButton::icon {
    fill: #000000;
    display: initial;
    width: 26px;
    height: 26px;
}.root::tabsList::tab:hover {
    background-color: value(color_36);
}.root::multiStateBoxWrapper {
    background-color: value(color_36);
    border: 1px solid #B4BBAC;
}.root::tabsList {
    background-color: value(color_38);
}@media value(mobileMediaQuery) {
    .root::tabsList::tab {
        font-size: 14px;
    }
}
